import{_ as a,o as s,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"3. 量子纠错: 逻辑 qubit / surface code / 现实挑战","description":"","frontmatter":{},"headers":[],"relativePath":"quantum/error-correction.md","filePath":"quantum/error-correction.md","lastUpdated":1788475713000}'),i={name:"quantum/error-correction.md"};function l(o,t,r,d,p,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_3-量子纠错-逻辑-qubit-surface-code-现实挑战" tabindex="-1">3. 量子纠错: 逻辑 qubit / surface code / 现实挑战 <a class="header-anchor" href="#_3-量子纠错-逻辑-qubit-surface-code-现实挑战" aria-label="Permalink to &quot;3. 量子纠错: 逻辑 qubit / surface code / 现实挑战&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>量子比特极其脆弱：环境噪声、测量错误、门错误都会让计算失效。量子计算要规模化，<strong>必须纠错</strong>。但量子纠错和经典纠错（信息论 §汉明码/RS）根本不同——因为<strong>量子态不能复制（no-cloning）</strong>，只能<strong>把 1 个逻辑 qubit 编码到多个物理 qubit + 周期性测量纠错</strong>。当前主流是 <strong>surface code</strong>。这一章讲清&quot;为什么纠错这么难、逻辑 qubit 怎么造、现在到哪一步了&quot;。</p><p>读完应能：</p><ol><li>说出经典纠错 vs 量子纠错的根本差异（no-cloning / 测量坍缩）。</li><li>理解逻辑 qubit 概念：多个物理 qubit 编码 1 个逻辑 qubit。</li><li>理解 surface code 的核心思想（网格 + stabilizer + 测量纠错）。</li><li>理解&quot;逻辑错误率 &lt; 物理错误率&quot;的阈值定理意义。</li><li>知道当前现实（logical qubit 时代、Y2Q 估计），不迷信炒作。</li></ol><hr><h2 id="一、为什么量子纠错和经典纠错完全不同" tabindex="-1">一、为什么量子纠错和经典纠错完全不同 <a class="header-anchor" href="#一、为什么量子纠错和经典纠错完全不同" aria-label="Permalink to &quot;一、为什么量子纠错和经典纠错完全不同&quot;">​</a></h2><h3 id="_1-1-经典纠错复习-信息论-§4" tabindex="-1">1.1 经典纠错复习（信息论 §4） <a class="header-anchor" href="#_1-1-经典纠错复习-信息论-§4" aria-label="Permalink to &quot;1.1 经典纠错复习（信息论 §4）&quot;">​</a></h3><p>汉明码：用冗余 bit（7 个物理 bit 编 4 个数据 bit），出错时多数投票纠正。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>经典: bit 可以复制 → 存多份 → 多数投票</span></span>
<span class="line"><span>       1011 → 1011 1011 1011 → 有一位翻 → 多数修回</span></span></code></pre></div><h3 id="_1-2-量子纠错的三个障碍" tabindex="-1">1.2 量子纠错的三个障碍 <a class="header-anchor" href="#_1-2-量子纠错的三个障碍" aria-label="Permalink to &quot;1.2 量子纠错的三个障碍&quot;">​</a></h3><table tabindex="0"><thead><tr><th>障碍</th><th>说明</th></tr></thead><tbody><tr><td><strong>No-cloning 定理</strong></td><td>量子态<strong>不能被复制</strong>（不可克隆），所以不能&quot;存多份投票&quot;</td></tr><tr><td><strong>测量坍缩</strong></td><td>直接测量会破坏叠加态（一测就坍缩成经典结果）</td></tr><tr><td><strong>错误连续</strong></td><td>错误不是&quot;0→1&quot;离散翻，而是连续的相位/振幅漂移</td></tr></tbody></table><h3 id="_1-3-量子纠错的突破思路" tabindex="-1">1.3 量子纠错的突破思路 <a class="header-anchor" href="#_1-3-量子纠错的突破思路" aria-label="Permalink to &quot;1.3 量子纠错的突破思路&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不复制态, 而是把&quot;逻辑态&quot;分布到多个物理 qubit 的纠缠态里</span></span>
<span class="line"><span>用&quot;稳定子测量&quot;(stabilizer measurement) 检测错误, 不破坏数据</span></span>
<span class="line"><span>错误是离散的(X/Z 两类) → 类比经典奇偶校验</span></span></code></pre></div><p>关键：<strong>纠错靠冗余编码 + 关联测量，不是复制</strong>。经典纠错可复制、量子靠纠缠。</p><hr><h2 id="二、逻辑-qubit-基础概念" tabindex="-1">二、逻辑 qubit：基础概念 <a class="header-anchor" href="#二、逻辑-qubit-基础概念" aria-label="Permalink to &quot;二、逻辑 qubit：基础概念&quot;">​</a></h2><h3 id="_2-1-定义" tabindex="-1">2.1 定义 <a class="header-anchor" href="#_2-1-定义" aria-label="Permalink to &quot;2.1 定义&quot;">​</a></h3><blockquote><p><strong>逻辑 qubit</strong> = 由多个物理 qubit 通过纠错码编码出的&quot;可靠&quot;量子比特。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 个逻辑 qubit (可靠)</span></span>
<span class="line"><span>  ↕ 编码</span></span>
<span class="line"><span>N 个物理 qubit (脆弱) + 周期性纠错</span></span></code></pre></div><ul><li>物理 qubit 是硬件里的真实比特（超导/离子阱/光子...）。</li><li>逻辑 qubit 是&quot;抽象出来的可靠计算单位&quot;——算法跑在逻辑 qubit 上。</li></ul><h3 id="_2-2-冗余比例" tabindex="-1">2.2 冗余比例 <a class="header-anchor" href="#_2-2-冗余比例" aria-label="Permalink to &quot;2.2 冗余比例&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编码</th><th>物理:逻辑</th><th>说明</th></tr></thead><tbody><tr><td>小演示码（Steane/Shor）</td><td>7:1</td><td>教学/小规模</td></tr><tr><td><strong>Surface code</strong></td><td>~100-1000:1</td><td>当前主流、容错阈值好</td></tr><tr><td>更高级</td><td>更多</td><td>追求更低开销</td></tr></tbody></table><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>这就是为什么&quot;Shor 要百万物理 qubit&quot;：分解 RSA-2048 需要 ~2-3k 个<strong>逻辑</strong> qubit，每个逻辑 qubit 又要 ~几百-上千个物理 qubit → 总物理 qubit 达百万级。</p></div><hr><h2 id="三、surface-code-当前主流" tabindex="-1">三、Surface code：当前主流 <a class="header-anchor" href="#三、surface-code-当前主流" aria-label="Permalink to &quot;三、Surface code：当前主流&quot;">​</a></h2><h3 id="_3-1-网格布局" tabindex="-1">3.1 网格布局 <a class="header-anchor" href="#_3-1-网格布局" aria-label="Permalink to &quot;3.1 网格布局&quot;">​</a></h3><p>Surface code 把物理 qubit 排成 2D 网格：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  数据 qubit (d): 存逻辑信息 (交叉点)</span></span>
<span class="line"><span>  测量 qubit (m): 检测错误 (稳定子测量)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  d ─ m ─ d ─ m ─ d</span></span>
<span class="line"><span>  │   │   │   │   │</span></span>
<span class="line"><span>  m ─ d ─ m ─ d ─ m</span></span>
<span class="line"><span>  │   │   │   │   │</span></span>
<span class="line"><span>  d ─ m ─ d ─ m ─ d</span></span></code></pre></div><ul><li><strong>数据 qubit</strong> 承载逻辑信息（X 和 Z 两类错误）。</li><li><strong>测量 qubit</strong> 周期性地做 stabilizer 测量（探测相邻数据位是否出错），<strong>不破坏数据</strong>。</li></ul><h3 id="_3-2-stabilizer-测量-关键机制" tabindex="-1">3.2 Stabilizer 测量（关键机制） <a class="header-anchor" href="#_3-2-stabilizer-测量-关键机制" aria-label="Permalink to &quot;3.2 Stabilizer 测量（关键机制）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>测量 qubit 与相邻数据 qubit 纠缠 → 测出&quot;奇偶性&quot; (stabilizer 本征值)</span></span>
<span class="line"><span>错误发生时 → 奇偶性翻转 → 检测到</span></span>
<span class="line"><span>→ 用&quot;错误综合征&quot;(syndrome) 定位错误位置 → 纠正</span></span></code></pre></div><ul><li>类比：像奇偶校验位，但<strong>测量不坍缩数据</strong>（因为测的是关联，不是数据本身）。</li><li>错误综合征 → 解算错误位置（经典解码，如 matching 算法）→ 施加纠正门。</li></ul><h3 id="_3-3-距离-distance-d" tabindex="-1">3.3 距离（distance）d <a class="header-anchor" href="#_3-3-距离-distance-d" aria-label="Permalink to &quot;3.3 距离（distance）d&quot;">​</a></h3><ul><li>Surface code 的<strong>距离 d</strong> = 网格边长（数据 qubit 每边数量）。</li><li>更大的 d → 能纠正更多错误 → 逻辑错误率指数下降（如果物理错误率低于阈值）。</li><li>纠错能力：能纠正 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">⌊</mo><mo stretchy="false">(</mo><mi>d</mi><mo>−</mo><mn>1</mn><mo stretchy="false">)</mo><mi mathvariant="normal">/</mi><mn>2</mn><mo stretchy="false">⌋</mo></mrow><annotation encoding="application/x-tex">\\lfloor (d-1)/2 \\rfloor</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⌊(</span><span class="mord mathnormal">d</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mord">/2</span><span class="mclose">⌋</span></span></span></span> 个错误链。</li></ul><h3 id="_3-4-阈值定理-threshold-theorem" tabindex="-1">3.4 阈值定理（Threshold Theorem） <a class="header-anchor" href="#_3-4-阈值定理-threshold-theorem" aria-label="Permalink to &quot;3.4 阈值定理（Threshold Theorem）&quot;">​</a></h3><blockquote><p>如果<strong>物理错误率低于某阈值</strong>（surface code 约 1%），那么增大码距离 d 就能<strong>指数级降低逻辑错误率</strong>——理论上可以无限制地可靠计算。</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物理错误率 &lt; 阈值 (≈1%)  → 逻辑错误率指数降</span></span>
<span class="line"><span>物理错误率 &gt; 阈值        → 越纠越错 (扩码无用)</span></span></code></pre></div><p>这就是&quot;<strong>容错量子计算是可能的</strong>&quot;的理论保证——前提是硬件好过阈值。</p><hr><h2 id="四、稳定子与纠错过程-更具体" tabindex="-1">四、稳定子与纠错过程（更具体） <a class="header-anchor" href="#四、稳定子与纠错过程-更具体" aria-label="Permalink to &quot;四、稳定子与纠错过程（更具体）&quot;">​</a></h2><h3 id="_4-1-两个-stabilizer-类型" tabindex="-1">4.1 两个 stabilizer 类型 <a class="header-anchor" href="#_4-1-两个-stabilizer-类型" aria-label="Permalink to &quot;4.1 两个 stabilizer 类型&quot;">​</a></h3><ul><li><strong>X-type stabilizer</strong>：检测 Z 错误（相位翻转）。</li><li><strong>Z-type stabilizer</strong>：检测 X 错误（比特翻转）。</li></ul><h3 id="_4-2-纠错循环" tabindex="-1">4.2 纠错循环 <a class="header-anchor" href="#_4-2-纠错循环" aria-label="Permalink to &quot;4.2 纠错循环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 周期性测量 stabilizer (每个测量 qubit)</span></span>
<span class="line"><span>2. 对比测量结果 (寻找&quot;错误综合征&quot;变化)</span></span>
<span class="line"><span>3. 解码: 用综合征图定位错误链 (经典算法, 如 Union-Find / MWPM)</span></span>
<span class="line"><span>4. 应用纠正门 (X 或 Z, 看错误类型)</span></span>
<span class="line"><span>5. 返回步骤 1 (持续, 因为错误连续发生)</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>纠错是<strong>持续在线</strong>的——不像经典存储&quot;纠一次&quot;，量子计算中错误不断产生，所以纠错要周期性进行，且纠错本身要快过错误累积。</p></div><h3 id="_4-3-容错门-fault-tolerant-gates" tabindex="-1">4.3 容错门（Fault-tolerant gates） <a class="header-anchor" href="#_4-3-容错门-fault-tolerant-gates" aria-label="Permalink to &quot;4.3 容错门（Fault-tolerant gates）&quot;">​</a></h3><ul><li>纠错码允许的&quot;逻辑门&quot;要满足<strong>容错性</strong>：门操作不把错误放大到不可控。</li><li>这极其复杂——<strong>Clifford 门容易，非 Clifford 门（T 门）难</strong>（需要 magic state distillation）。</li><li>实现逻辑门 + 纠错 = 整个&quot;容错量子计算&quot;的最大工程难题。</li></ul><hr><h2 id="五、当前现实-2026-视角" tabindex="-1">五、当前现实（2026 视角） <a class="header-anchor" href="#五、当前现实-2026-视角" aria-label="Permalink to &quot;五、当前现实（2026 视角）&quot;">​</a></h2><h3 id="_5-1-里程碑" tabindex="-1">5.1 里程碑 <a class="header-anchor" href="#_5-1-里程碑" aria-label="Permalink to &quot;5.1 里程碑&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>进展</th></tr></thead><tbody><tr><td>2021-2023</td><td>多个团队演示<strong>逻辑 qubit 错误率 &lt; 物理 qubit</strong>（small distance）</td></tr><tr><td>2024-2025</td><td>Google (Willow) 等演示 surface code 增大 distance 后逻辑错误率下降（关键验证）</td></tr><tr><td>2026+</td><td>冲击 ~100 逻辑 qubit；<strong>错误率仍未低到跑 Shor</strong></td></tr><tr><td>远期</td><td>百万物理 qubit 才能威胁 RSA-2048</td></tr></tbody></table><h3 id="_5-2-挑战清单" tabindex="-1">5.2 挑战清单 <a class="header-anchor" href="#_5-2-挑战清单" aria-label="Permalink to &quot;5.2 挑战清单&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 物理错误率要 &lt; 阈值 (≈1%)   — 硬件质量</span></span>
<span class="line"><span>2. 大规模 2D 网格 + 快速经典解码  — 工程</span></span>
<span class="line"><span>3. 容错逻辑门 (T 门 / magic state)  — 理论+工程</span></span>
<span class="line"><span>4. 冷却/稳定 (超导需 mK 温度)     — 物理</span></span>
<span class="line"><span>5. 与经典 CPU 协同 (混合计算)      — 系统</span></span></code></pre></div><h3 id="_5-3-y2q-years-to-quantum" tabindex="-1">5.3 Y2Q（Years to Quantum） <a class="header-anchor" href="#_5-3-y2q-years-to-quantum" aria-label="Permalink to &quot;5.3 Y2Q（Years to Quantum）&quot;">​</a></h3><ul><li>估算：<strong>10-30 年</strong>才可能有实用规模量子计算机。</li><li><strong>现在就该做</strong>的：<strong>后量子密码迁移</strong>（公钥换成 PQC），因为&quot;今天截获、明天解密&quot;（harvest-now-decrypt-later）是现实威胁。</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>别听&quot;明年破解&quot;的炒作，也别无视风险。<strong>现在值得做的</strong>：把 RSA/ECC 迁移到 PQC（NIST 已标准化 Kyber/Dilithium），尤其是长期保密数据。这是&quot;确定性需求 + 不确定时间表&quot;的经典风险管理。</p></div><hr><h2 id="六、与信息论-密码学的接口" tabindex="-1">六、与信息论/密码学的接口 <a class="header-anchor" href="#六、与信息论-密码学的接口" aria-label="Permalink to &quot;六、与信息论/密码学的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>经典对应</th><th>量子</th></tr></thead><tbody><tr><td>冗余编码</td><td>汉明/RS（§info-theory）</td><td>surface code / stabilizer</td></tr><tr><td>奇偶校验</td><td>parity check</td><td>stabilizer 测量</td></tr><tr><td>纠错能力</td><td>最小距离 → 纠 t 错</td><td>码距离 d → 纠 (d-1)/2 错</td></tr><tr><td>阈值</td><td>香农容量</td><td>阈值定理（1%）</td></tr><tr><td>安全威胁</td><td>RSA/ECC</td><td>Shor / Grover（§algorithms）</td></tr><tr><td>防御</td><td>换长密钥</td><td>PQC（Kyber/Dilithium）</td></tr></tbody></table><hr><h2 id="七、结束-速查表" tabindex="-1">七、结束 + 速查表 <a class="header-anchor" href="#七、结束-速查表" aria-label="Permalink to &quot;七、结束 + 速查表&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>一页快速唤回：</p><ul><li><strong>量子纠错 ≠ 经典纠错</strong>：no-cloning（不能复制）、测量坍缩、错误连续 → 靠纠缠编码 + stabilizer 测量。</li><li><strong>逻辑 qubit</strong> = 多个物理 qubit 编码的可靠比特；算法跑在逻辑 qubit 上。</li><li><strong>Surface code</strong>：2D 网格 + 数据/测量 qubit + stabilizer 周期测量 + 经典解码。</li><li><strong>距离 d</strong>：越大能纠越多错；逻辑错误率指数降（低于阈值时）。</li><li><strong>阈值定理</strong>：物理错误率 &lt; ~1% → 容错可行。</li><li><strong>容错门</strong>：Clifford 易、T 门难（magic state）。</li><li><strong>现状</strong>（2026）：~100 逻辑 qubit 时代；Shor 要百万物理 qubit → Y2Q 10-30 年。</li><li><strong>现在该做</strong>：PQC 迁移（Kyber/Dilithium）——harvest-now-decrypt-later 是现实威胁。</li></ul></div><hr><p>回主目录: <a href="./">量子计算卷 README</a>.</p>`,65)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
